1	import { cookies } from "next/headers";
2	
3	// This is a lightweight, app-level "who's holding the device" marker — not
4	// a security boundary. The real access-control boundary is the owner's
5	// Supabase Auth session (checked by RLS on every query). A cashier can't
6	// see or touch another business's data no matter what this cookie says.
7	export type CashierSession = {
8	  cashierId: string;
9	  businessId: string;
10	  name: string;
11	  role: "kasir" | "manajer";
12	};
13	
14	const COOKIE_NAME = "kasirku_cashier_session";
15	
16	export async function getCashierSession(
17	  businessId: string,
18	): Promise<CashierSession | null> {
19	  const cookieStore = await cookies();
20	  const raw = cookieStore.get(COOKIE_NAME)?.value;
21	  if (!raw) return null;
22	
23	  try {
24	    const session = JSON.parse(raw) as CashierSession;
25	    if (session.businessId !== businessId) return null;
26	    return session;
27	  } catch {
28	    return null;
29	  }
30	}
31	
32	export async function setCashierSession(session: CashierSession) {
33	  const cookieStore = await cookies();
34	  cookieStore.set(COOKIE_NAME, JSON.stringify(session), {
35	    httpOnly: true,
36	    sameSite: "lax",
37	    path: "/",
38	    maxAge: 60 * 60 * 12, // ~12 hours, roughly a shift
39	  });
40	}
41	
42	export async function clearCashierSession() {
43	  const cookieStore = await cookies();
44	  cookieStore.delete(COOKIE_NAME);
45	}
