97	export type TaxServiceState = { error: string | null; saved: boolean };
98	
99	export async function updateTaxService(
100	  businessId: string,
101	  _prevState: TaxServiceState,
102	  formData: FormData,
103	): Promise<TaxServiceState> {
104	  const taxEnabled = formData.get("taxEnabled") === "on";
105	  const serviceEnabled = formData.get("serviceEnabled") === "on";
106	  const taxRate = Number(formData.get("taxRate"));
107	  const serviceRate = Number(formData.get("serviceRate"));
108	
109	  if (taxEnabled && (Number.isNaN(taxRate) || taxRate < 0 || taxRate > 100)) {
110	    return { error: "Tarif PPN harus 0–100%.", saved: false };
111	  }
112	  if (serviceEnabled && (Number.isNaN(serviceRate) || serviceRate < 0 || serviceRate > 100)) {
113	    return { error: "Tarif biaya layanan harus 0–100%.", saved: false };
114	  }
115	
116	  const supabase = await createClient();
117	  const { error } = await supabase
118	    .from("businesses")
119	    .update({
120	      tax_enabled: taxEnabled,
121	      tax_rate: taxEnabled ? taxRate : 0,
122	      service_enabled: serviceEnabled,
123	      service_rate: serviceEnabled ? serviceRate : 0,
124	    })
125	    .eq("id", businessId);
