30	  const {
31	    data: { user },
32	  } = await supabase.auth.getUser();
33	
34	  const authPages = ["/login", "/signup"];
35	  const isAuthPage = authPages.some((path) =>
36	    request.nextUrl.pathname.startsWith(path),
37	  );
38	  // /order/* adalah halaman self-order pelanggan (scan QR) — tanpa login.
39	  const isPublicPath =
40	    isAuthPage || request.nextUrl.pathname.startsWith("/order");
41	
42	  if (!user && !isPublicPath) {
43	    const url = request.nextUrl.clone();
44	    url.pathname = "/login";
45	    return NextResponse.redirect(url);
46	  }
47	
48	  if (user && isAuthPage) {
49	    const url = request.nextUrl.clone();
50	    url.pathname = "/dashboard";
51	    return NextResponse.redirect(url);
52	  }
53	
54	  return supabaseResponse;
55	}
